javascript:(function() {
    const canvas = document.getElementById('aniguard-canvas');
    if (!canvas) return alert('Buka minigame AniGuard dulu ya!');

    window.aniGuardConfig = window.aniGuardConfig || {
        stopMana: 8,         
        innerCount: 11,      
        innerRadius: 65,     
        frenzyMana: 25,      
        randomCount: 16,     
        intervalMs: 5500     
    };

    if (window.aniGuardBotInterval) {
        clearInterval(window.aniGuardBotInterval);
        window.aniGuardBotInterval = null;
    }

    let isBotRunning = false;

    function drawAdaptiveCustom() {
        const inkEl = document.getElementById('aniguard-ink');
        let currentMana = inkEl ? parseInt(inkEl.innerText) : 100;

        if (currentMana <= window.aniGuardConfig.stopMana) return; 

        const rect = canvas.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = (rect.height / 2) + 12; 

        function drawDot(x, y) {
            canvas.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, clientX: x, clientY: y }));
            canvas.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: x + 4, clientY: y + 4 }));
            window.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));
        }

        const innerCount = window.aniGuardConfig.innerCount;
        const radius = window.aniGuardConfig.innerRadius;
        for (let i = 0; i < innerCount; i++) {
            let angle = (i * (Math.PI * 2 / innerCount));
            drawDot(rect.left + cx + Math.cos(angle) * radius, rect.top + cy + Math.sin(angle) * radius);
        }

        if (currentMana > window.aniGuardConfig.frenzyMana) {
            const edgePoints = [
                {x: 15, y: 15}, {x: rect.width - 15, y: 15},
                {x: 15, y: rect.height - 15}, {x: rect.width - 15, y: rect.height - 15},
                {x: cx, y: 15}, {x: cx, y: rect.height - 15},
                {x: 15, y: cy}, {x: rect.width - 15, y: cy}
            ];
            edgePoints.forEach(p => drawDot(rect.left + p.x, rect.top + p.y));

            const randCount = window.aniGuardConfig.randomCount;
            for (let i = 0; i < randCount; i++) {
                let rx = Math.random() * (rect.width - 40) + 20;
                let ry = Math.random() * (rect.height - 40) + 20;
                drawDot(rect.left + rx, rect.top + ry);
            }
        }
    }

    let container = document.getElementById('ani-bot-container');
    if (container) container.remove(); 

    container = document.createElement('div');
    container.id = 'ani-bot-container';
    container.style.cssText = 'position:fixed; top:80px; right:20px; z-index:999999; font-family:sans-serif;';

    let btnGroup = document.createElement('div');
    btnGroup.style.cssText = 'display:flex; gap:6px; justify-content:flex-end;';

    let btnMain = document.createElement('button');
    btnMain.innerHTML = '🛡️ Adaptive: OFF';
    btnMain.style.cssText = 'background:#ef4444; color:white; padding:10px 15px; border-radius:8px; font-weight:bold; cursor:pointer; border:2px solid #fff; box-shadow:0 4px 6px rgba(0,0,0,0.3); transition: background 0.2s;';

    let btnSettings = document.createElement('button');
    btnSettings.innerHTML = '⚙️';
    btnSettings.title = 'Pengaturan Bot';
    btnSettings.style.cssText = 'background:#334155; color:white; padding:10px 12px; border-radius:8px; font-weight:bold; cursor:pointer; border:2px solid #fff; box-shadow:0 4px 6px rgba(0,0,0,0.3); transition: background 0.2s;';

    btnGroup.appendChild(btnMain);
    btnGroup.appendChild(btnSettings);
    container.appendChild(btnGroup);

    let panel = document.createElement('div');
    panel.style.cssText = 'margin-top:10px; width:250px; background:rgba(15,23,42,0.95); color:white; padding:15px; border-radius:10px; border:1px solid #334155; display:none; flex-direction:column; gap:12px; box-shadow:0 10px 20px rgba(0,0,0,0.6); backdrop-filter:blur(4px);';

    function createInputGroup(label, key, step=1) {
        let wrap = document.createElement('div');
        wrap.style.cssText = 'display:flex; justify-content:space-between; align-items:center; font-size:13px; font-weight:bold; color:#cbd5e1;';
        let lbl = document.createElement('label');
        lbl.innerText = label;
        let inp = document.createElement('input');
        inp.type = 'number';
        inp.step = step;
        inp.value = window.aniGuardConfig[key];
        inp.style.cssText = 'width:70px; padding:6px; border-radius:6px; border:1px solid #475569; background:#1e293b; color:#fff; text-align:center; outline:none; font-weight:bold;';
        
        inp.onchange = (e) => { window.aniGuardConfig[key] = parseInt(e.target.value); };
        
        wrap.appendChild(lbl);
        wrap.appendChild(inp);
        return wrap;
    }

    panel.appendChild(createInputGroup('Jeda Waktu (ms)', 'intervalMs', 100));
    panel.appendChild(createInputGroup('Titik Lingkaran Dalam', 'innerCount'));
    panel.appendChild(createInputGroup('Radius Lingkaran Dalam', 'innerRadius'));
    panel.appendChild(createInputGroup('Titik Ranjau Acak', 'randomCount'));
    panel.appendChild(createInputGroup('Setop Frenzy (Mana %)', 'frenzyMana'));
    panel.appendChild(createInputGroup('Setop Total (Mana %)', 'stopMana'));

    let btnClose = document.createElement('button');
    btnClose.innerHTML = '✔ Simpan & Terapkan';
    btnClose.style.cssText = 'margin-top:8px; background:#3b82f6; color:white; padding:10px; border:none; border-radius:6px; font-weight:bold; cursor:pointer; transition: background 0.2s;';

    btnClose.onclick = () => {
        panel.style.display = 'none';
        btnSettings.style.background = '#334155';

        if (isBotRunning) {
            clearInterval(window.aniGuardBotInterval);
            window.aniGuardBotInterval = setInterval(drawAdaptiveCustom, window.aniGuardConfig.intervalMs);
        }
    };
    panel.appendChild(btnClose);

    container.appendChild(panel);
    document.body.appendChild(container);

    btnSettings.onclick = () => {
        let isClosed = panel.style.display === 'none';
        panel.style.display = isClosed ? 'flex' : 'none';
        btnSettings.style.background = isClosed ? '#3b82f6' : '#334155';
    };

    btnMain.onclick = () => {
        isBotRunning = !isBotRunning;
        if (isBotRunning) {
            btnMain.style.background = '#22c55e';
            btnMain.innerHTML = '🛡️ Adaptive: ON';
            drawAdaptiveCustom(); 
            window.aniGuardBotInterval = setInterval(drawAdaptiveCustom, window.aniGuardConfig.intervalMs);
        } else {
            btnMain.style.background = '#ef4444';
            btnMain.innerHTML = '🛡️ Adaptive: OFF';
            clearInterval(window.aniGuardBotInterval);
            window.aniGuardBotInterval = null;
        }
    };
})();